import { View, Text, FlatList, ActivityIndicator, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const SERVER_DATA = [
  { id: "1", name: "Чихэвч" },
  { id: "2", name: "Гар цаг" },
  { id: "3", name: "Нарны шил" },
];

function App() {
  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setItems(SERVER_DATA);
      setLoading(false);
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  if (loading) {
    return (
      <View style={styles.center}>
        <ActivityIndicator nativeID="spinner" size="large" color="#2563eb" />
        <Text style={styles.hint}>Ачаалж байна...</Text>
      </View>
    );
  }

  return (
    <FlatList
      style={styles.screen}
      data={items}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
    />
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, justifyContent: "center", alignItems: "center", gap: 12 },
  hint: { color: "#71717a" },
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  row: { backgroundColor: "#fff", padding: 16, margin: 8, borderRadius: 12, fontSize: 16 },
});

registerRootComponent(App);
